#include "codec-oracle.cpp"
#undef main
#define ZSTD_STATIC_LINKING_ONLY
#include <zstd.h>
#include <map>
std::map<std::string,int> coverage;
uint32_t zread(const Bytes& data,size_t position,int count){if(position+count>data.size())throw std::runtime_error("coverage parser bounds");uint32_t value=0;for(int i=0;i<count;++i)value|=uint32_t(data[position+i])<<(i*8);return value;}
void trace(const Bytes& data){size_t position=0;int blocks=0;while(position<data.size()){uint32_t magic=zread(data,position,4);position+=4;if((magic&0xfffffff0)==0x184d2a50){position+=4+zread(data,position,4);++coverage["skippable"];continue;}int descriptor=data.at(position++);bool single=(descriptor&32)!=0;if(!single)++position;int dictionary=descriptor&3;position+=dictionary==3?4:dictionary;int code=descriptor>>6;position+=code==0?(single?1:0):code==1?2:code==2?4:8;bool last;do{uint32_t header=zread(data,position,3);position+=3;last=(header&1)!=0;int type=(header>>1)&3,size=header>>3;++coverage["block-"+std::to_string(type)];++blocks;if(type==2){size_t begin=position;int literal=data.at(begin)&3,field=(data.at(begin)>>2)&3;int headerSize,raw,packed;if(literal<2){headerSize=field==1?2:field==3?3:1;raw=zread(data,begin,headerSize)>>(headerSize==1?3:4);packed=literal==0?raw:1;}else{headerSize=field<2?3:field==2?4:5;uint64_t fields=zread(data,begin,std::min(headerSize,4));if(headerSize==5)fields|=uint64_t(data.at(begin+4))<<32;int bits=field<2?10:field==2?14:18;raw=(fields>>4)&((1<<bits)-1);packed=fields>>(4+bits);if(literal==2)++coverage[data.at(begin+headerSize)>=128?"huffman-direct-weights":"huffman-fse-weights"];++coverage[field==0?"huffman-one-stream":"huffman-four-streams"];}++coverage["literal-"+std::to_string(literal)];size_t seq=begin+headerSize+packed;int count=data.at(seq++);if(count==255){count=0x7f00+zread(data,seq,2);seq+=2;}else if(count>127)count=((count-128)<<8)+data.at(seq++);if(count){int modes=data.at(seq);++coverage["LL-mode-"+std::to_string(modes>>6)];++coverage["OF-mode-"+std::to_string((modes>>4)&3)];++coverage["ML-mode-"+std::to_string((modes>>2)&3)];}}position+=type==1?1:size;}while(!last);if(descriptor&4){position+=4;++coverage["checksum"];}if(!single)++coverage["window-descriptor"];}if(blocks>1)++coverage["multiple-blocks"];}
void zcheck(size_t status){if(ZSTD_isError(status))throw std::runtime_error(ZSTD_getErrorName(status));}
void zverify(const std::string& name,const Bytes& packed,const Bytes& expected){Bytes decoded(expected.size());size_t n=ZSTD_decompress(decoded.data(),decoded.size(),packed.data(),packed.size());zcheck(n);if(n!=expected.size()||decoded!=expected)throw std::runtime_error("Zstd native decode mismatch: "+name);trace(packed);emit(name,"zstd",packed,decoded);}
Bytes zpattern(int size,int kind){Bytes raw(size);uint32_t random=0x12345678;for(int i=0;i<size;++i){random=random*1664525+1013904223;raw[i]=kind==0?42:kind==1?uint8_t(i%17):kind==2?uint8_t(random>>24):kind==3?uint8_t((random>>24)&15):kind==4?uint8_t((i%1024<600)?0:(random>>24)&31):uint8_t((i%8192<4096)?(i%29):((random>>24)&63));}return raw;}
void zgenerate(){for(int kind=0;kind<6;++kind)for(int size:{0,1,7,31,128,1024,4096,65536,131072,262144})for(int level:{-5,1,3,9,19})for(int checksum:{0,1}){
 if(kind==2&&size>4096&&(level!=1||checksum))continue;
 if(size<4096&&level>3)continue;
 auto raw=zpattern(size,kind);Bytes packed(ZSTD_compressBound(raw.size()));ZSTD_CCtx* context=ZSTD_createCCtx();if(!context)throw std::runtime_error("Zstd allocation failed");zcheck(ZSTD_CCtx_setParameter(context,ZSTD_c_compressionLevel,level));zcheck(ZSTD_CCtx_setParameter(context,ZSTD_c_checksumFlag,checksum));zcheck(ZSTD_CCtx_setParameter(context,ZSTD_c_contentSizeFlag,(level==3)?0:1));
 if(kind==5)zcheck(ZSTD_CCtx_setParameter(context,ZSTD_c_targetCBlockSize,2048));
 size_t length=ZSTD_compress2(context,packed.data(),packed.size(),raw.data(),raw.size());ZSTD_freeCCtx(context);zcheck(length);packed.resize(length);zverify("pattern-"+std::to_string(kind)+"-"+std::to_string(size)+"-"+std::to_string(level)+"-"+std::to_string(checksum),packed,raw);
 }
 for(int size:{0,1,255,256,131072})for(int rle:{0,1}){auto raw=zpattern(size,0);Bytes frame{0x28,0xb5,0x2f,0xfd,0xa0};little(frame,size,4);little(frame,(uint32_t(size)<<3)|(rle?3:1),3);if(rle)frame.push_back(42);else frame.insert(frame.end(),raw.begin(),raw.end());zverify("manual-"+std::to_string(size)+"-"+std::to_string(rle),frame,raw);}
 auto raw=zpattern(32768,3);Bytes frame(ZSTD_compressBound(raw.size()));size_t length=ZSTD_compress(frame.data(),frame.size(),raw.data(),raw.size(),5);zcheck(length);frame.resize(length);Bytes joined=frame;joined.insert(joined.end(),frame.begin(),frame.end());Bytes doubled=raw;doubled.insert(doubled.end(),raw.begin(),raw.end());zverify("concatenated",joined,doubled);Bytes skip{0x50,0x2a,0x4d,0x18,3,0,0,0,1,2,3};skip.insert(skip.end(),joined.begin(),joined.end());zverify("skippable-concatenated",skip,doubled);
 {Bytes packed{0x28,0xb5,0x2f,0xfd,0x20,16,69,0,0,9,65,1,84,1,0,12,1};zverify("literal-rle-all-sequence-rle",packed,Bytes(16,65));}
 for(int distance:{2,3,4})for(int repeat:{0,1,2}){Bytes raw=zpattern(32,1);Bytes frame{0x28,0xb5,0x2f,0xfd,0x20,42};little(frame,32u<<3,3);frame.insert(frame.end(),raw.begin(),raw.end());Bytes block{0,1,84,0,2,2,uint8_t(4|(distance-1))};little(frame,uint32_t(block.size()<<3)|4,3);frame.insert(frame.end(),block.begin(),block.end());for(int i=0;i<5;++i)raw.push_back(raw[raw.size()-distance]);block=Bytes{0,1,84,0,uint8_t(repeat==2?0:1),2,uint8_t(repeat==2?1:(2|repeat))};little(frame,uint32_t(block.size()<<3)|5,3);frame.insert(frame.end(),block.begin(),block.end());int offset=repeat==0?4:repeat==1?distance-1:1;for(int i=0;i<5;++i)raw.push_back(raw[raw.size()-offset]);zverify("repeat-offset-"+std::to_string(distance)+"-"+std::to_string(repeat),frame,raw);}
 for(int type:{1,3,4,12})for(int filter:{0,1,2})for(int split:{BLOSC_ALWAYS_SPLIT,BLOSC_NEVER_SPLIT}){auto bytes=zpattern(8195,4);Bytes packed(bytes.size()+BLOSC_MAX_OVERHEAD),decoded(bytes.size());blosc_set_splitmode(split);int size=blosc_compress_ctx(9,filter,type,bytes.size(),bytes.data(),packed.data(),packed.size(),"zstd",2048,1);if(size<=0)throw std::runtime_error("Zstd Blosc compression failed");packed.resize(size);if(blosc_decompress_ctx(packed.data(),decoded.data(),decoded.size(),1)!=decoded.size()||decoded!=bytes)throw std::runtime_error("Zstd Blosc mismatch");emit("blosc-"+std::to_string(type)+"-"+std::to_string(filter)+"-"+std::to_string(split),"frame",packed,decoded);}
}
void zcompat(const fs::path& directory){for(const auto& file:fs::directory_iterator(directory)){auto name=file.path().filename().string();if(file.path().extension()!=".cdata"||name.find("zstd")==std::string::npos)continue;std::ifstream in(file.path(),std::ios::binary);Bytes packed((std::istreambuf_iterator<char>(in)),{});size_t length,compressed,block;blosc_cbuffer_sizes(packed.data(),&length,&compressed,&block);if(length>16*1024*1024||compressed!=packed.size())throw std::runtime_error("Invalid compatibility frame");Bytes decoded(length);if(blosc_decompress_ctx(packed.data(),decoded.data(),decoded.size(),1)!=length)throw std::runtime_error("Native historical Zstd decode failed");emit("compat-"+name,"frame",packed,decoded);}}
int main(int argc,char** argv){try{if(argc!=3)throw std::runtime_error("usage: zstd-reference output.json c-blosc-compat-directory");blosc_init();output.open(std::string(argv[1])+".tmp");output<<"[\n";zgenerate();zcompat(argv[2]);output<<"\n]\n";output.close();if(!MoveFileExW(fs::path(std::string(argv[1])+".tmp").c_str(),fs::path(argv[1]).c_str(),MOVEFILE_REPLACE_EXISTING|MOVEFILE_WRITE_THROUGH))throw std::runtime_error("Could not publish verified fixture");blosc_destroy();for(const auto& entry:coverage)std::cout<<entry.first<<"="<<entry.second<<'\n';std::cout<<"Verified "<<emitted<<" native Zstd fixtures\n";return 0;}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
